graph
  D[(Plan)]
  x1@{ label: "Ship it" }
  D@{ shape: inv_trapezoid, label: "**bold** step" }
  n_2 --> B[\Run tests/]
  E e1@--> D@{ shape: odd, label: "x < y" }
  C -.- label .- n_2["long label that keeps going well past the wrapping width"]
  A["Run tests"]
  D --x C["Plan"]
  n_2 --x|cross| B[/a "quoted" step\]
  C & Ünï -->|lbl| Start
  x1 & Ünï == thick ==> x1
  B
  Ünï --o C["Run tests"]
  Start@{ shape: lined-cylinder }
  A e1@--> Ünï{Plan}
  漢 -.-> E{fa:fa-check step}
  D@{ label: "fa:fa-check step" }
  E --x n_2{$$E=mc2$$}
  Ünï -.- label .- Start@{ shape: hourglass }
  Start & x1 --x C
  D ---> D@{ shape: delay, label: "x < y" }
  n_2 --o n_2[[$$E=mc2$$]]
  subgraph B["Ünï group"]
    n_2 -.- label .- Start
  end
  subgraph 漢["Group"]
    B -- text --> Start
  end
  B[/tab	here\]

graph BT
  A & A -.-> E
  C -.- E@{ shape: flag }
  A@{ shape: bang, label: "long label that keeps going well past the wrapping width" }
  E -.- D>Plan]
  B -. dotted .-> D{{Ship it}}
  C <--> E{tab	here}
  C & E -.- label .- C
  C & D e2@==> A
  D e1@--> D{{**bold** step}}
  E --x B[(tab	here)]
  A & C -.- label .- E
  B@{ label: "Plan" }
  B & A -.- B
  B@{ shape: doc }
  E ==> B@{ shape: squareRect, label: "**bold** step" }
  C e1@--> B:::hot
  D{tab	here}
  B --> E["Run tests"]
  A ---> B@{ shape: cloud, label: "Ünï" }
  D --> C{a "quoted" step}
  subgraph E["Group"]
    B -.- label .- D
  end
  A & C --o A
  E -.-> C[\long label that keeps going well past the wrapping width\]

flowchart LR
  Ünï & C e2@==> D
  Ünï([fa:fa-check step])
  x1 --x x1([**bold** step])
  n_2{{x < y}}
  A & D -.-> B
  Ünï & n_2 -. dotted .-> Ünï
  Ünï -- text --> B:::hot
  D e2@==> D@{ shape: flag, label: "Run tests" }
  A[/Plan\]
  Ünï <--> B@{ shape: lean_right }
  n_2 == thick ==> E>$$E=mc2$$]
  漢 <--> E
  n_2 --- n_2@{ shape: bang }
  A -- "quoted" --> A@{ label: "Ünï" }
  C ~~~ x1(((Plan)))
  n_2{{fa:fa-check step}}
  Ünï == thick ==> Ünï@{ label: "$$E=mc2$$" }
  C & E e1@--> D
  B -->|lbl| x1[/a "quoted" step\]
  漢(((Ünï)))
  subgraph n_2["Group"]
    B --> Ünï
  end
  B@{ shape: lin-doc, label: "fa:fa-check step" }
  B --> n_2["Ship it"]
  漢@{ shape: doc }
  Ünï ---> A[\Ünï/]
  B -->|lbl| x1[\**bold** step\]
  D & E e1@--> C

